&lt;div class="two-panel" id="two-panel"&gt;

  &lt;div class="main-panel"&gt;

    &lt;h2&gt;Inupiaq&lt;/h2&gt;

    &lt;p&gt;
    Taiguaqta by Edna Ahgeak MacLean

    Nukatpiaġruk niksiksuqtuq.

    Niksiksullaturuq.

    Niksiksullatuviñi?
    &lt;/p&gt;

  &lt;/div&gt;

  &lt;div class="side-panel" id="side-panel"&gt;

    &lt;h2&gt;English&lt;/h2&gt;

    &lt;p&gt;
    Let's Read! by Edna Agheak MacLean

    The boy is fishing.

    He enjoys fishing.

    Do you like fishing?
    &lt;/p&gt;

  &lt;/div&gt;

  &lt;button
    class="toggle-button"
    id="toggle-button"
    onclick="togglePanel()"&gt;
    ›
  &lt;/button&gt;

&lt;/div&gt;

&lt;script&gt;
function togglePanel() {

  const container = document.getElementById("two-panel");

  container.classList.toggle("collapsed");

  const button = document.getElementById("toggle-button");

  if (container.classList.contains("collapsed")) {
    button.textContent = "‹";
  } else {
    button.textContent = "›";
  }
}
&lt;/script&gt;
